import{_ as o,o as t,c as a,ag as r}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/collaborate/folders-breadcrumb.png",l="/docs/images/collaborate/folders-move-dialog.png",g=JSON.parse(`{"title":"Organize documents in folders","description":"Organize a workspace's documents into folders, find documents in the list, and move, rename, copy, or delete them.","frontmatter":{"title":"Organize documents in folders","description":"Organize a workspace's documents into folders, find documents in the list, and move, rename, copy, or delete them.","type":"how-to"},"headers":[],"relativePath":"collaborate/folders.md","filePath":"collaborate/folders.md"}`),s={name:"collaborate/folders.md"};function i(d,e,c,h,m,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="organize-documents-in-folders" tabindex="-1">Organize documents in folders <a class="header-anchor" href="#organize-documents-in-folders" aria-label="Permalink to &quot;Organize documents in folders&quot;">​</a></h1><p>Folders group a workspace&#39;s documents so they&#39;re easier to find. Any document type can go in a folder, and folders can nest to any depth.</p><p>Folders only organize. They don&#39;t change who can open a document: every member of the workspace can open everything in it.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Any member can create and rename folders, and rename or copy documents.</li><li>To move or delete a folder or document, you need to have created it, or own the workspace.</li><li>Folders exist inside one workspace. Open a workspace&#39;s documents list to use them.</li></ul></div><h2 id="create-a-folder" tabindex="-1">Create a folder <a class="header-anchor" href="#create-a-folder" aria-label="Permalink to &quot;Create a folder&quot;">​</a></h2><ol><li>Open the workspace&#39;s documents list, or the folder you want the new folder in.</li><li>Click <strong>New</strong> &gt; <strong>New folder</strong>.</li><li>Enter a <strong>Name</strong> and click <strong>Create</strong>.</li></ol><p>The folder appears in the list. To build a structure such as <code>Team</code> &gt; <code>Projects</code> &gt; <code>2026</code>, open each folder and create the next one inside it.</p><h2 id="open-a-folder" tabindex="-1">Open a folder <a class="header-anchor" href="#open-a-folder" aria-label="Permalink to &quot;Open a folder&quot;">​</a></h2><ol><li>Click a folder in the list to see what&#39;s inside.</li><li>To go back up, click a folder name in the breadcrumb at the top of the list. <strong>Home</strong> is the top level of the workspace.</li></ol><p><img src="'+n+'" alt="Documents list inside a nested folder with the Home / Team / Projects breadcrumb"></p><h2 id="move-documents-into-a-folder" tabindex="-1">Move documents into a folder <a class="header-anchor" href="#move-documents-into-a-folder" aria-label="Permalink to &quot;Move documents into a folder&quot;">​</a></h2><ol><li>Select the documents with the checkboxes. <code>Shift</code>-click to select a range.</li><li>Drag the selection onto a folder in the list, or onto a folder name in the breadcrumb.</li></ol><p>The documents move to that folder.</p><h3 id="move-with-a-dialog" tabindex="-1">Move with a dialog <a class="header-anchor" href="#move-with-a-dialog" aria-label="Permalink to &quot;Move with a dialog&quot;">​</a></h3><ol><li>Click <strong>⋯</strong> at the end of a document&#39;s row and select <strong>Move to...</strong>. For several documents, select them and click <strong>Move to…</strong> in the bar above the list.</li><li>Choose a <strong>Workspace</strong> and a <strong>Folder</strong>. <strong>Home</strong> is the top of the workspace.</li><li>Click <strong>Move</strong>.</li></ol><p>The dialog is also how you move a document to another workspace you belong to.</p><p><img src="'+l+'" alt="Move dialog with Workspace and Folder menus, the Folder menu open on the workspace&#39;s folders"></p><h2 id="move-a-folder" tabindex="-1">Move a folder <a class="header-anchor" href="#move-a-folder" aria-label="Permalink to &quot;Move a folder&quot;">​</a></h2><ol><li>Click <strong>⋯</strong> at the end of the folder&#39;s row and select <strong>Move to...</strong>.</li><li>Choose the destination <strong>Folder</strong> and click <strong>Move</strong>.</li></ol><p>Everything inside moves with it. A folder can&#39;t move to another workspace; if you choose one, only the documents in your selection move.</p><h2 id="rename-a-folder-or-document" tabindex="-1">Rename a folder or document <a class="header-anchor" href="#rename-a-folder-or-document" aria-label="Permalink to &quot;Rename a folder or document&quot;">​</a></h2><ol><li>Click <strong>⋯</strong> at the end of the row and select <strong>Rename</strong>.</li><li>Enter the new name and click <strong>Rename</strong>.</li></ol><p>You can also rename a document from inside it by clicking its title in the header. See <a href="/docs/collaborate/edit-together.html#rename-a-document">Edit together</a>.</p><h2 id="make-a-copy-of-a-document" tabindex="-1">Make a copy of a document <a class="header-anchor" href="#make-a-copy-of-a-document" aria-label="Permalink to &quot;Make a copy of a document&quot;">​</a></h2><ol><li>Click <strong>⋯</strong> at the end of the document&#39;s row. For several documents, select them instead.</li><li>Select <strong>Make a copy</strong>, or click <strong>Make a copy</strong> in the bar above the list.</li></ol><p>The copy is named <code>&lt;title&gt; (copy)</code> and lands in the same folder. It has the content only, without comments, share links, or version history.</p><h2 id="delete-a-folder" tabindex="-1">Delete a folder <a class="header-anchor" href="#delete-a-folder" aria-label="Permalink to &quot;Delete a folder&quot;">​</a></h2><ol><li>Click <strong>⋯</strong> at the end of the folder&#39;s row and select <strong>Delete</strong>.</li><li>In the confirmation, click <strong>Delete</strong>.</li></ol><p>The folder and its subfolders are deleted. The documents inside them move back to the top of the workspace, so nothing is lost. A deleted folder can&#39;t be restored.</p><p>If your selection includes documents as well as a folder, the bar above the list shows <strong>Delete</strong>, and the selected documents go to the <a href="/docs/collaborate/trash.html">Trash</a>.</p><h2 id="find-a-document" tabindex="-1">Find a document <a class="header-anchor" href="#find-a-document" aria-label="Permalink to &quot;Find a document&quot;">​</a></h2><ul><li><strong>Search</strong>: type in <strong>Search by title...</strong> above the list.</li><li><strong>Filter</strong>: click <strong>Type</strong> and check the document types you want. Click <strong>Clear filters</strong> to show everything again.</li><li><strong>Sort</strong>: click a column heading.</li></ul><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Only documents you created, or any document if you own the workspace, can be dragged. To move a folder, use <strong>Move to...</strong>.</li><li>A folder can&#39;t be shared or given its own permissions. Share each document instead.</li><li>The <strong>⋯</strong> menu offers <strong>Move to...</strong> and <strong>Delete</strong> on every folder, but they fail with an error if you didn&#39;t create the folder and don&#39;t own the workspace.</li><li>A document&#39;s <strong>⋯</strong> menu shows <strong>Move to...</strong> and <strong>Move to Trash</strong> only if you created it or own the workspace. In the bar above the list, <strong>Move to…</strong> and <strong>Move to Trash</strong> are grayed out when the selection includes a document you can&#39;t move.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/collaborate/trash.html">Trash</a> to restore a document you deleted.</li><li><a href="/docs/files/upload.html">Upload files</a> to add files to the folder you have open.</li><li><a href="/docs/collaborate/workspaces.html">Workspaces and roles</a> for who can move and delete.</li><li><a href="/docs/collaborate/templates.html">Templates</a> to start a document in the current folder.</li></ul>',36)])])}const p=o(s,[["render",i]]);export{g as __pageData,p as default};
